// Writes web/src/themes.css and web/src/themes.ts from shadcn's own theme presets (the `theme` and `baseColor` axes of
// `shadcn create`), read from the registry's init endpoint. Run: node web/tools/gen-themes.mjs (needs the network once).
// The generated files are committed; the app itself never fetches anything.

import { writeFileSync } from 'node:fs';
import { join } from 'node:path';

const THEMES = [
  'neutral',
  'stone',
  'zinc',
  'mauve',
  'olive',
  'mist',
  'taupe',
  'red',
  'rose',
  'orange',
  'amber',
  'yellow',
  'lime',
  'green',
  'emerald',
  'teal',
  'cyan',
  'sky',
  'blue',
  'indigo',
  'violet',
  'purple',
  'fuchsia',
  'pink',
];
const BASE_COLORS = new Set(['neutral', 'stone', 'zinc', 'mauve', 'olive', 'mist', 'taupe']);
// The variables a preset sets; the structure (radius, fonts) stays the app's own.
const SKIP = new Set(['radius']);

const out = join(import.meta.dirname, '..', 'src');
let css = '/* Generated by web/tools/gen-themes.mjs from shadcn theme presets. Do not edit. */\n';
const list = [];
for (const theme of THEMES) {
  const params = new URLSearchParams({
    base: 'base',
    style: 'nova',
    baseColor: BASE_COLORS.has(theme) ? theme : 'neutral',
    theme,
    iconLibrary: 'lucide',
    font: 'inter',
    rtl: 'true',
    menuAccent: 'subtle',
    menuColor: 'default',
    radius: 'default',
  });
  const response = await fetch(`https://ui.shadcn.com/init?${params}`);
  if (!response.ok) throw new Error(`${theme}: ${response.status}`);
  const { cssVars } = await response.json();
  const block = (vars) =>
    Object.entries(vars)
      .filter(([name]) => !SKIP.has(name))
      .map(([name, value]) => `  --${name}: ${value};`)
      .join('\n');
  css += `\n:root[data-preset="${theme}"] {\n${block(cssVars.light)}\n}\n`;
  css += `\n:root.dark[data-preset="${theme}"] {\n${block(cssVars.dark)}\n}\n`;
  list.push({ id: theme, light: cssVars.light.primary, dark: cssVars.dark.primary });
}
writeFileSync(join(out, 'themes.css'), css);
writeFileSync(
  join(out, 'themes.ts'),
  `// Generated by web/tools/gen-themes.mjs. The swatch of each shadcn theme preset (its primary colour).\nexport const PRESETS = ${JSON.stringify(list, null, 2)} as const;\nexport type PresetId = (typeof PRESETS)[number]['id'];\n`,
);
console.log(`wrote ${THEMES.length} presets`);
